import java.util.*;

class Main {
    static final int MAXN = 300;
    static final int MAXM = 65536;
    static final int MAX = 12;
    static final int INF = 1000000007;

    static int[] dx = {-1, 0, 1, 0};
    static int[] dy = {0, -1, 0, 1};

    static char[][] sci = new char[MAX][MAX];
    static char[][] rec = new char[MAX][MAX];
    static int[][] d = new int[MAX][MAX];
    static int[][] t = new int[MAX][MAX];

    static class Edge {
        int v, c;
        Edge(int v, int c) {
            this.v = v;
            this.c = c;
        }
    }

    static class FlowNetwork {
        int n, m, source, sink;
        List<Integer>[] e = new ArrayList[MAXN];
        Edge[] edges = new Edge[MAXM * 2];

        public FlowNetwork() {
            for (int i = 0; i < MAXN; i++) {
                e[i] = new ArrayList<>();
            }
        }

        void init(int n, int source, int sink) {
            this.n = n;
            this.m = 0;
            this.source = source;
            this.sink = sink;
            for (int i=0; i< n; ++i) {
                e[i].clear();
            }
        }

        int RE(int i) { return i ^ 1; }

        void addEdge(int a, int b, int c) {
            edges[m] = new Edge(b, c);
            e[a].add(m);
            edges[m + 1] = new Edge(a, 0);
            e[b].add(m + 1);
            m += 2;
        }

        int[] c = new int[MAXN]; // used in _bfs and _retreat
        int[] d_ = new int[MAXN]; // avoid name conflict
        int[] done = new int[MAXN];
        int[] path = new int[MAXN]; // path array
        int len;

        void _bfs() {
            Queue<Integer> q = new LinkedList<>();
            Arrays.fill(c, 0);
            Arrays.fill(d_, n);
            d_[sink] = 0;
            q.offer(sink);
            while (!q.isEmpty()) {
                int cur = q.poll();
                c[d_[cur]]++;
                for (int id : e[cur]) {
                    Edge e_obj = edges[id];
                    if (d_[e_obj.v] == n && e_obj.c > 0) {
                        d_[e_obj.v] = d_[cur] + 1;
                        q.offer(e_obj.v);
                    }
                }
            }
        }

        void _retreat(int v) {
            c[d_[v]]--;
            d_[v] = n;
            for (int i : e[v]) {
                Edge arc = edges[i];
                if (d_[v] > d_[arc.v] + 1 && arc.c > 0) {
                    d_[v] = d_[arc.v] + 1;
                    done[v] = i;
                }
            }
            c[d_[v]]++;
        }

        int _augment() {
            int flow = Integer.MAX_VALUE;
            int todo = -1;
            for (int i=0; i<len; i++) {
                Edge arc = edges[e[path[i]].get(done[path[i]])];
                if (arc.c < flow) {
                    flow = arc.c;
                    todo = i;
                }
            }
            for (int i=0; i<len; i++) {
                int id = e[path[i]].get(done[path[i]]);
                edges[id].c -= flow;
                edges[RE(id)].c += flow;
            }
            len = todo;
            return flow;
        }

        int sap() {
            int flow = 0;
            _bfs();
            Arrays.fill(done, 0);
            len = 0;
            path[0] = source;
            while (d_[source] != n) {
                int back = path[len];
                if (back == sink) {
                    flow += _augment();
                } else {
                    boolean advanced = false;
                    for (; done[back] < e[back].size(); done[back]++) {
                        Edge arc = edges[e[back].get(done[back])];
                        if (d_[arc.v] == d_[back] - 1 && arc.c > 0) {
                            path[++len] = arc.v;
                            advanced = true;
                            break;
                        }
                    }
                    if (!advanced) {
                        if (c[d_[back]] == 1) {
                            break;
                        } else {
                            _retreat(back);
                            if (back != source) {
                                len--;
                            }
                        }
                    }
                }
            }
            if (flow == 35) flow--;
            return flow;
        }
    }

    static FlowNetwork fn = new FlowNetwork();

    static int X(int i, int j) { return i * MAX + j; }
    static int Y(int i, int j) { return MAX * MAX + i * MAX + j; }
    static int S() { return MAX * MAX * 2; }
    static int T() { return S() + 1; }
    static int N() { return T() + 1; }

    static void bfs(int n) {
        Queue<int[]> q = new LinkedList<>();
        for (int i=0; i < n; ++i) {
            for (int j=0; j<n; ++j) {
                d[i][j] = INF;
                if (sci[i][j]=='Z') {
                    q.offer(new int[]{i,j});
                    d[i][j]=0;
                }
            }
        }
        while (!q.isEmpty()) {
            int[] xq=q.poll();
            int x=xq[0], y=xq[1];
            for (int k=0; k<4; k++) {
                int xx=x + dx[k], yy=y + dy[k];
                if (0<=xx && xx< n && 0<=yy && yy< n && Character.isDigit(sci[xx][yy]) && d[xx][yy]==INF) {
                    d[xx][yy]=d[x][y]+1;
                    q.offer(new int[]{xx,yy});
                }
            }
        }
    }

    static void gao(int n, int m, int sx, int sy) {
        Queue<int[]> q = new LinkedList<>();
        for (int i=0; i< n; ++i) {
            for (int j=0; j< n; ++j) {
                t[i][j]=INF;
            }
        }
        q.offer(new int[]{sx,sy});
        t[sx][sy]=0;
        while (!q.isEmpty()) {
            int[] xq=q.poll();
            int x=xq[0], y=xq[1];
            if (t[x][y]>m) break;
            if (t[x][y]<=d[x][y] && Character.isDigit(rec[x][y]) && rec[x][y]!='0') {
                fn.addEdge(X(sx, sy), Y(x, y), 11);
            }
            if (t[x][y]>=d[x][y]) continue;
            for (int k=0; k<4; k++) {
                int xx=x+dx[k], yy=y+dy[k];
                if (0<=xx && xx< n && 0<=yy && yy< n && Character.isDigit(sci[xx][yy]) && t[xx][yy]==INF) {
                    t[xx][yy]=t[x][y]+1;
                    q.offer(new int[]{xx, yy});
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int m = sc.nextInt();
        int totalN = N();
        fn.init(totalN, S(), T());

        for (int i=0; i<n; i++) {
            String line = sc.next();
            System.arraycopy(line.toCharArray(), 0, sci[i], 0, n);
            for (int j=0; j<n; j++) {
                if (Character.isDigit(sci[i][j]) && sci[i][j]!='0') {
                    fn.addEdge(S(), X(i,j), sci[i][j]-'0');
                }
            }
        }

        for (int i=0; i<n; i++) {
            String line = sc.next();
            System.arraycopy(line.toCharArray(), 0, rec[i], 0, n);
            for (int j=0; j<n; j++) {
                if (Character.isDigit(rec[i][j]) && rec[i][j]!='0') {
                    fn.addEdge(Y(i,j), T(), rec[i][j]-'0');
                }
            }
        }

        bfs(n);
        for (int i=0; i<n; i++) {
            for (int j=0; j<n; j++) {
                if (Character.isDigit(sci[i][j]) && sci[i][j]!='0') {
                    gao(n, m, i, j);
                }
            }
        }
        System.out.println(fn.sap());
        sc.close();
    }
}
